{
  "discoveries": [
    "地面: 茶色っぽい砂と石が散らばっている → **ground**（地面の色・構成）",
    "植生: 背の低い草や苔が広がり、遠くに雪をいただいた山が見える → **terrain_vegetation**（地形・植生）",
    "舗装: 砂利道 → **pavement**（路面材質）"
  ],
  "discriminationHint": "今回、**terrain_vegetation** が唯一確認できた手がかりとして機能しました。雪山と植生の乏しさは北欧の高緯度地域でよく見られますが、同様の特徴はグリーンランドでも出現します。したがって、**terrain_vegetation** だけで決定するのはリスクが高い点を覚えておきましょう。",
提供されていないため、**見落とし**の判定はできません。",
  "judgmentUnavailable": true,
  "missedClues": [
    {
      "slot": "traffic_side",
      "whatWasThere": "❓道路の走行側が写っていれば、右側通行か左側通行かが確認できます。北欧（例：アイスランド）は右側通行、グリーンランドは左側通行が多いです。"
    ,
      "whyItMatters": "通行方向は国別にほぼ一定なので、たった1枚で絞り込みが可能です。"
    },
    {
      "slot": "road_marking",
      "whatWasThere": "❓白線や黄線、路面標示の有無・形状は地域ごとの規則があります。例えば、ヨーロッパでは黄色の中央線は一般的でありません。"
    ,
      "whyItMatters": "路面標示は都市部・郊外でも見えやすく、国特有のデザインが手がかりになります。"
    },
    {
      "slot": "sign",
      "whatWasThere": "❓標識の形・色が確認できれば、使用文字や色彩配慮（例: 青底の道路標識は北欧で多い）を手掛かりにできます。"
    ,
      "whyItMatters": "標識は言語情報がなくてもデザインで国を絞り込めます。"
    },
    {
      "slot": "script",
      "whatWasThere": "❓看板や広告の文字形状（ラテン文字、サンスクリット系、独自文字）をスケッチすれば、言語圏の推測が可能です。"
    ,
      "whyItMatters": "文字の形は国別に偏りが大きく、確信度を上げる材料になります。"
    }
  ],
  "nextPriority": [
    "① **traffic_side**（走行側）をまず確認し、右側通行か左側通行かをメモする。",
    "② **road_marking**（路面標示）を探し、白線・黄線・路面の塗装色を記録する。",
    "③ **sign**（標識）と **script**（看板文字）をできるだけ詳細に描写する。文字は読めなくても形を残すだけで有効です。"
  ],
  "summary": "terrain_vegetation で方向性を付けたのは良いですが、右側通行か左側通行か、路面標示・標識・文字といった基本的な手がかりが不足していました。次回は上記 3 つのスロットを優先的に探し、見えるものはすべて簡潔に書き留める練習をすると、確信度を大きく上げられます。"

  ,
  "vocabulary": [
    {"canonicalTerm":"traffic_side","learnerWrote":"車はどちら側を走っている？（走行車線）","note":"道路上の走行側を示す用語です"},
    {"canonicalTerm":"road_marking","learnerWrote":"道路の白線・黄線","note":"路面に描かれた線や標示の総称"},
    {"canonicalTerm":"bollard","learnerWrote":"車道脇の短い杭・ポール","note":"道路側を区切るための小さな柱"},
    {"canonicalTerm":"pole","learnerWrote":"電柱・街灯の形","note":"電柱や街灯などの柱状構造物"},
    {"canonicalTerm":"sign","learnerWrote":"標識の形・色","note":"道路標識や案内板の形状・配色"}
  ]

  ,
  "wrongReasoning": [
    {
      "explanation":"「グリーンランドであれば道路があれば民家とか人工物が見えるはず」という前提は、全地域に当てはまらないため判断根拠として弱いです。"
    ,
      "slot":"terrain_vegetation"
    }
  ]

